def find_substring_to_reverse(n, s):
    for i in range(n):
        for j in range(i + 1, n):
            # Check if reversing the substring s[i:j+1] results in a lexicographically smaller string
            if s[:i] + s[i:j+1][::-1] + s[j+1:] < s:
                return "YES", i + 1, j + 1
    return "NO"

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    s = data[1]

    result = find_substring_to_reverse(n, s)
    if result == "NO":
        print(result)
    else:
        print(result[0])
        print(result[1], result[2])

